export const isBoss=n=>!!n&&n.id!=='admin-target'&&(['vampire','dark-self','baron','abbess','ashwing','troll','lich','witch','hunter','ghost','werewolf'].includes(n.species)||n.role==='captain'||n.id==='bone-keeper');
export const enemyName=n=>n?.name||({'skeleton-sword':'Скелет-мечник','skeleton-bow':'Скелет-лучник','skeleton-mage':'Скелет-маг',troll:'Лесной тролль',hunter:'Обезумевший охотник',hare:'Кролик',witch:'Ведьма',raven:'Ворон',lich:'Лич',ghost:'Звонарь',wolf:'Волк'}[n?.species]||'Противник');
export function selectBoss(targets,camera,preferred=null){if(preferred?.hp>0&&preferred.g.visible)return preferred;return targets.filter(n=>isBoss(n)&&n.hp>0&&n.g.visible&&(n.aggro||n.hit&&camera.position.distanceTo(n.g.position)<50)).sort((a,b)=>camera.position.distanceToSquared(a.g.position)-camera.position.distanceToSquared(b.g.position))[0]||null}
export function renderBossHud(n,doc=globalThis.document){const hud=doc?.querySelector('#boss-hud');if(!hud)return;const alive=!!n&&n.hp>0;hud.hidden=!alive;doc.body?.classList?.toggle?.('boss-fight',alive);if(!alive)return;const title=doc.querySelector('#boss-title'),fill=doc.querySelector('#boss-fill');title.textContent=enemyName(n)+(n.level||n.fixedLevel?' · ур. '+(n.level||n.fixedLevel):'')+' · '+Math.ceil(n.hp)+' / '+n.maxHp;fill.style.width=Math.max(0,Math.min(100,n.hp/n.maxHp*100))+'%'}
